test_snippets.java:
public static void check(Solution solution) {
    assert Arrays.equals(solution.findWords(new int[]{{'o','a','a','n'},{'e','t','a','e'},{'i','h','k','r'},{'i','f','l','v'}}, new int[]{'oath','pea','eat','rain'}), new int[]{'oath', 'eat'});
    assert Arrays.equals(solution.findWords(new int[]{{"a","a"}}, new int[]{"a"}), new int[]{'a'});
    assert Arrays.equals(solution.findWords(new int[]{{"o","a","a","n"},{"e","t","a","e"},{"i","h","k","r"},{"i","f","l","v"}}, new int[]{"oath","pea","eat","rain"}), new int[]{'oath', 'eat'});
    assert Arrays.equals(solution.findWords(), Error: Solution.findWords() missing 2 required positional arguments: 'board' and 'words');
    assert Arrays.equals(solution.findWords(new int[]{{"a"},{"a"}}, new int[]{"a"}), new int[]{'a'});
